func TestGettersCatalogMeasurementUnit(t *testing.T) {
	t.Run("GetMeasurementUnit", func(t *testing.T) {
		t.Parallel()
		// Arrange
		obj := &CatalogMeasurementUnit{}
		var expected *MeasurementUnit
		obj.MeasurementUnit = expected

		// Act & Assert
		assert.Equal(t, expected, obj.GetMeasurementUnit(), "getter should return the property value")
	})

	t.Run("GetMeasurementUnit_NilValue", func(t *testing.T) {
		t.Parallel()
		// Arrange
		obj := &CatalogMeasurementUnit{}
		obj.MeasurementUnit = nil

		// Act & Assert
		assert.Nil(t, obj.GetMeasurementUnit(), "getter should return nil when property is nil")
	})

	t.Run("GetMeasurementUnit_NilReceiver", func(t *testing.T) {
		t.Parallel()
		var obj *CatalogMeasurementUnit
		// Should not panic - getters should handle nil receiver gracefully
		defer func() {
			if r := recover(); r != nil {
				t.Errorf("Getter panicked on nil receiver: %v", r)
			}
		}()
		_ = obj.GetMeasurementUnit() // Should return zero value
	})

	t.Run("GetPrecision", func(t *testing.T) {
		t.Parallel()
		// Arrange
		obj := &CatalogMeasurementUnit{}
		var expected *int
		obj.Precision = expected

		// Act & Assert
		assert.Equal(t, expected, obj.GetPrecision(), "getter should return the property value")
	})

	t.Run("GetPrecision_NilValue", func(t *testing.T) {
		t.Parallel()
		// Arrange
		obj := &CatalogMeasurementUnit{}
		obj.Precision = nil

		// Act & Assert
		assert.Nil(t, obj.GetPrecision(), "getter should return nil when property is nil")
	})

	t.Run("GetPrecision_NilReceiver", func(t *testing.T) {
		t.Parallel()
		var obj *CatalogMeasurementUnit
		// Should not panic - getters should handle nil receiver gracefully
		defer func() {
			if r := recover(); r != nil {
				t.Errorf("Getter panicked on nil receiver: %v", r)
			}
		}()
		_ = obj.GetPrecision() // Should return zero value
	})

}

